/* @lc app=leetcode id=3346 lang=kotlin */ class Solution { fun ub(a: List<Int>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun lb(a: List<Int>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun maxFrequency(nums: IntArray, k: Int, numOperations: Int): Int = nums.sorted().let { a -> a.indices.maxOf { i -> maxOf((ub(a, a[i].toLong()) - lb(a, a[i].toLong())).let { c -> c + minOf(numOperations, ub(a, a[i].toLong() + k) - lb(a, a[i].toLong() - k) - c) }, minOf(numOperations, ub(a, a[i].toLong() + 2L * k) - lb(a, a[i].toLong()))) } } }